/** Outer guard: original product errors remain transient; exported failures never retain them. */
public static final class FaultSinkGuard implements org.junit.jupiter.api.extension.InvocationInterceptor {
  @Override
  public void interceptTestMethod(Invocation<Void> invocation,
      org.junit.jupiter.api.extension.ReflectiveInvocationContext<java.lang.reflect.Method> method,
      org.junit.jupiter.api.extension.ExtensionContext extension) throws Throwable {
    guarded(invocation, extension);
  }

  @Override
  public void interceptTestTemplateMethod(Invocation<Void> invocation,
      org.junit.jupiter.api.extension.ReflectiveInvocationContext<java.lang.reflect.Method> method,
      org.junit.jupiter.api.extension.ExtensionContext extension) throws Throwable {
    guarded(invocation, extension);
  }

  @Override
  public void interceptBeforeEachMethod(Invocation<Void> invocation,
      org.junit.jupiter.api.extension.ReflectiveInvocationContext<java.lang.reflect.Method> method,
      org.junit.jupiter.api.extension.ExtensionContext extension) throws Throwable {
    try {
      invocation.proceed();
    } catch (Throwable original) {
      throw FaultCapture.safeLifecycleFailure(original);
    }
  }

  @Override
  public void interceptAfterEachMethod(Invocation<Void> invocation,
      org.junit.jupiter.api.extension.ReflectiveInvocationContext<java.lang.reflect.Method> method,
      org.junit.jupiter.api.extension.ExtensionContext extension) throws Throwable {
    try {
      invocation.proceed();
    } catch (Throwable original) {
      throw FaultCapture.safeLifecycleFailure(original);
    }
  }

  private static void guarded(Invocation<Void> invocation,
      org.junit.jupiter.api.extension.ExtensionContext extension) throws Throwable {
    Throwable primary = null;
    FaultCase observation = null;
    try {
      if (extension.getConfigurationParameter("junit.jupiter.execution.parallel.enabled")
          .map(Boolean::parseBoolean).orElse(false)) {
        throw new AssertionError("FAULT_PREREQUISITE");
      }
      observation = FaultCapture.beginCase(!extension.getRequiredTestMethod().getName()
          .equals("syntheticFaultSinkScannerDetectsIndependentEncodedControls"));
      invocation.proceed();
    } catch (Throwable original) {
      primary = original;
    } finally {
      FaultCapture.finishCase(observation, primary);
    }
  }
}

private enum FaultCode { PREREQUISITE, ORIGINAL_FAILURE, INCOMPLETE, LEAK, RESTORATION }

private static AssertionError closedFault(FaultCode code, int ordinal, int leaks, int failures) {
  // Plain AssertionError(String), never an original cause/suppressed/expected-actual wrapper.
  FaultCapture.fail(); // Every exported observer failure is durable in the sticky ledger.
  return new AssertionError("FAULT_" + code.name() + " ordinal=" + ordinal
      + " leaks=" + leaks + " failures=" + Math.max(failures, FaultCapture.FAILURES.get()));
}

/** Class-owned quarantine survives case failures and actual late context/peer shutdown. */
private static final class FaultCapture {
  private static final java.util.concurrent.locks.ReentrantLock SERIAL =
      new java.util.concurrent.locks.ReentrantLock();
  private static final AtomicReference<FaultCase> CURRENT = new AtomicReference<>();
  private static final ThreadLocal<FaultCase> PEER_CASE = new ThreadLocal<>();
  private static final List<FaultCase> CASES = new java.util.concurrent.CopyOnWriteArrayList<>();
  private static final List<SinkBytes> SINKS = new java.util.concurrent.CopyOnWriteArrayList<>();
  private static final AtomicInteger FAILURES = new AtomicInteger(), LEAKS = new AtomicInteger();
  private static final AtomicInteger EVENTS = new AtomicInteger(), BYTES = new AtomicInteger();
  private static final AtomicInteger RAW_FIELDS = new AtomicInteger(), PRODUCT_EVENTS = new AtomicInteger();
  private static final AtomicInteger UNIQUE_EVENTS = new AtomicInteger();
  private static final Map<ch.qos.logback.classic.spi.ILoggingEvent, RawObservation> RAW_IDENTITIES =
      java.util.Collections.synchronizedMap(new java.util.IdentityHashMap<>());
  private static final ThreadLocal<RawObservation> RAW_CURRENT = new ThreadLocal<>();
  private static final java.util.concurrent.atomic.AtomicLong OBSERVATION_VERSION =
      new java.util.concurrent.atomic.AtomicLong();
  private static final int AGGREGATE_LIMIT = 32 * 1024 * 1024;
  private static final int FIELD_LIMIT = 1024 * 1024;
  private static final int EVENT_LIMIT = 4096;
  private static volatile LogQuarantine logging;
  private static final FaultCase LIFECYCLE = new FaultCase(0, false);

  static FaultCase beginCase(boolean productionRequired) {
    SERIAL.lock();
    try {
      if (CURRENT.get() != null) {
        fail();
        throw closedFault(FaultCode.PREREQUISITE, 0, 0, FAILURES.get());
      }
      var next = new FaultCase(CASES.size() + 1, productionRequired);
      CASES.add(next);
      CURRENT.set(next);
      if (logging == null) {
        var installed = new LogQuarantine();
        logging = installed; // Retain partial-install restoration ownership immediately.
        installed.install();
      }
      logging.preRelease(false);
      if (FAILURES.get() != 0) {
        throw closedFault(FaultCode.PREREQUISITE, next.ordinal, LEAKS.get(), FAILURES.get());
      }
      return next;
    } catch (Throwable original) {
      throwable(original);
      CURRENT.set(null);
      SERIAL.unlock();
      throw closedFault(FaultCode.PREREQUISITE, CASES.size(), LEAKS.get(), FAILURES.get());
    }
  }

  static FaultCase currentCase() {
    var active = CURRENT.get();
    return active == null ? LIFECYCLE : active;
  }

  static void finishCase(FaultCase observation, Throwable primary) {
    try {
      if (observation == null) {
        if (primary != null) {
          throwable(primary);
          throw closedFault(FaultCode.PREREQUISITE, CASES.size(), LEAKS.get(), FAILURES.get());
        }
        return;
      }
      observation.original = primary;
      try { observation.drain(); }
      catch (Throwable cleanup) { throwable(cleanup); fail(); }
      for (Scenario scenario : observation.scenarios) {
        throwable(scenario.failure.get());
        throwable(scenario.peerFailure.get());
      }
      for (Throwable peerError : observation.peerErrors) { throwable(peerError); }
      for (SourceStopOwner owner : observation.owners) {
        throwable(owner.failure.get());
        throwable(owner.guardFailure.get());
      }
      throwable(primary);
      try { logging.verifyRoutes(observation.hasRelease()); }
      catch (Throwable unavailable) { throwable(unavailable); fail(); }
      try { logging.probeRoutes(); }
      catch (Throwable unavailable) { throwable(unavailable); fail(); }
      try { logging.inspectStatus(); }
      catch (Throwable unavailable) { throwable(unavailable); fail(); }
      observation.requireActualProduction();
      scanAll();
      observation.countOnlyReport();
      if (primary != null || FAILURES.get() != 0 || LEAKS.get() != 0) {
        throw closedFault(primary != null ? FaultCode.ORIGINAL_FAILURE
            : LEAKS.get() != 0 ? FaultCode.LEAK : FaultCode.INCOMPLETE,
            observation.ordinal, LEAKS.get(), FAILURES.get());
      }
    } catch (Throwable original) {
      if (observation != null && original != primary) {
        throwable(original);
      }
      // Even accessor, graph, cleanup and scanner failures cross only this closed boundary.
      throw closedFault(primary != null ? FaultCode.ORIGINAL_FAILURE : FaultCode.INCOMPLETE,
          observation == null ? 0 : observation.ordinal, LEAKS.get(), FAILURES.get());
    } finally {
      CURRENT.set(null);
      if (SERIAL.isHeldByCurrentThread()) {
        SERIAL.unlock();
      }
    }
  }

  static AssertionError safeLifecycleFailure(Throwable original) {
    try {
      throwable(original);
      scanAll();
    } catch (Throwable ignored) {
      fail();
    }
    return closedFault(FaultCode.ORIGINAL_FAILURE, 0, LEAKS.get(), FAILURES.get());
  }

  static void finishClass(Throwable primary, boolean resourcesClosed) {
    boolean restored = false;
    boolean closureProved = false;
    boolean finalScansComplete = false;
    try {
      throwable(primary);
      for (FaultCase observation : CASES) {
        try { observation.drain(); }
        catch (Throwable cleanup) { throwable(cleanup); fail(); }
        throwable(observation.original);
        for (Scenario scenario : observation.scenarios) {
          throwable(scenario.failure.get());
          throwable(scenario.peerFailure.get());
        }
        for (Throwable peerError : observation.peerErrors) { throwable(peerError); }
        for (SourceStopOwner owner : observation.owners) {
          throwable(owner.failure.get());
          throwable(owner.guardFailure.get());
        }
      }
      try { LIFECYCLE.drain(); }
      catch (Throwable cleanup) { throwable(cleanup); fail(); }
      for (Throwable peerError : LIFECYCLE.peerErrors) { throwable(peerError); }
