      if (!closureProved) { fail(); }
      if (logging != null) {
        try { logging.verifyRoutes(true); }
        catch (Throwable unavailable) { throwable(unavailable); fail(); }
        try { logging.inspectStatus(); }
        catch (Throwable unavailable) { throwable(unavailable); fail(); }
      }
      boolean preRestoreScansComplete = terminalScan();
      // A failed/unobserved pre-restoration inventory keeps the original outputs quarantined.
      if (closureProved && preRestoreScansComplete && FAILURES.get() == 0 && logging != null) {
        try { logging.restore(); restored = true; }
        catch (Throwable restoreFailure) { throwable(restoreFailure); fail(); }
      }
    } catch (Throwable lateFailure) {
      throwable(lateFailure);
      fail();
    } finally {
      // Independent terminal phase runs after every close/restore failure and before ANY wipe.
      if (logging != null) {
        try { logging.inspectStatus(); }
        catch (Throwable statusFailure) { throwable(statusFailure); fail(); }
      }
      finalScansComplete = terminalScan();
      if (!closureProved || !restored || !finalScansComplete || FAILURES.get() != 0) {
        if (logging != null) {
          try { logging.retainQuarantine(); }
          catch (Throwable retentionFailure) { throwable(retentionFailure); fail(); }
          try { logging.inspectStatus(); }
          catch (Throwable statusFailure) { throwable(statusFailure); fail(); }
        }
        // Retention itself can produce a new error. Scan it independently, but never dispose.
        terminalScan();
      } else {
        // Successful restoration alone is insufficient; only the proved final scan grants wipe.
        for (SinkBytes sink : SINKS) { Arrays.fill(sink.bytes, (byte) 0); }
        SINKS.clear();
        RAW_IDENTITIES.clear();
        logging.wipe();
        for (FaultCase observation : CASES) { observation.dispose(); }
        LIFECYCLE.dispose();
        BY_TEST.clear();
        BY_SESSION.clear();
        STOP_OWNERS.clear();
        CASES.clear();
      }
    }
    if (primary != null || !closureProved || !restored || !finalScansComplete
        || FAILURES.get() != 0 || LEAKS.get() != 0) {
