  }

  static void fail() { FAILURES.incrementAndGet(); }

  static boolean reserve(int bytes) {
    if (bytes < 0 || bytes > AGGREGATE_LIMIT) { fail(); return false; }
    while (true) {
      int current = BYTES.get();
      if (current > AGGREGATE_LIMIT - bytes) { fail(); return false; }
      if (BYTES.compareAndSet(current, current + bytes)) { return true; }
    }
  }

  static FaultCase responseCase() {
    var peer = PEER_CASE.get();
    return peer == null ? currentCase() : peer;
  }

  static void observe(String label, Object existing) {
    // Only already-returned typed values; never invokes an arbitrary object's toString.
    try {
      typed(label, existing, 0);
    } catch (Throwable ignored) {
      fail();
    }
  }

  private static void typed(String label, Object value, int depth) {
    if (depth > 32) { fail(); return; }
    if (value == null) { return; }
    if (value instanceof String text) {
      if (text.length() > FIELD_LIMIT / 4) { fail(); return; }
      byte[] bytes = text.getBytes(StandardCharsets.UTF_8);
      try { capture(label, bytes, false); }
      finally { Arrays.fill(bytes, (byte) 0); }
    } else if (value instanceof byte[] bytes) {
      capture(label, bytes, false);
    } else if (value instanceof char[] chars) {
      if (chars.length > FIELD_LIMIT / 4) { fail(); return; }
      typed(label, new String(chars), depth + 1);
    } else if (value instanceof JsonNode node) {
      if (node.isObject()) {
        node.fields().forEachRemaining(field -> {
          typed(label, field.getKey(), depth + 1);
          typed(label, field.getValue(), depth + 1);
        });
      } else if (node.isArray()) {
        node.forEach(child -> typed(label, child, depth + 1));
      } else if (node.isTextual()) {
        typed(label, node.textValue(), depth + 1);
