  void drain() {
    // Actual operation/peer exit is the barrier; counter zero alone never grants completion.
    for (Thread caller : callers) {
      if (caller != Thread.currentThread()) { joinUninterruptibly(caller); }
    }
    for (SourceStopOwner owner : owners) {
      try { owner.drainUninterruptibly(); }
      catch (Throwable cleanup) { FaultCapture.throwable(cleanup); FaultCapture.fail(); }
    }
    for (Thread peer : peers) {
      if (peer != Thread.currentThread()) { joinUninterruptibly(peer); }
    }
    if (!resourcesComplete()) { FaultCapture.fail(); }
    for (Scenario scenario : scenarios) {
      if (scenario.problemSource && hasRelease()
          && (sourceAttempts.get() != 1 || sourcePositive.get() != 1)) {
        FaultCapture.fail();
