    return callers.stream().noneMatch(thread -> thread != Thread.currentThread() && thread.isAlive())
        && peers.stream().noneMatch(thread -> thread != Thread.currentThread() && thread.isAlive())
        && activePeers.get() == 0 && peerExits.get() == peerEntries.get()
